-- ── hand-written: the market supplier ───────────────────────────────────────────────────────────
-- The company's supplier for sellers in the market who are not on the list, made the first time
-- it is asked for. Two purchases that both find none take turns, and the second finds the first's.
CREATE FUNCTION app.market_supplier() RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_supplier uuid;
  v_name text := 'Market seller';
  v_try integer := 1;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role does not buy from the market' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT m.supplier_id INTO v_supplier FROM public.market_suppliers m WHERE m.tenant_id = v_tenant;
  IF FOUND THEN
    RETURN v_supplier;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('market-supplier:' || v_tenant::text, 0));
  SELECT m.supplier_id INTO v_supplier FROM public.market_suppliers m WHERE m.tenant_id = v_tenant;
  IF FOUND THEN
    RETURN v_supplier;
  END IF;
  -- A supplier of that name already on the list is someone else: the market supplier takes the next free name.
  WHILE EXISTS (SELECT 1 FROM public.suppliers s WHERE s.tenant_id = v_tenant AND lower(s.name) = lower(v_name)) LOOP
    v_try := v_try + 1;
    v_name := 'Market seller ' || v_try;
  END LOOP;
  INSERT INTO public.suppliers (tenant_id, name, registration_type, supplier_type, created_by, updated_by)
    VALUES (v_tenant, v_name, 'unregistered', 'individual', v_user, v_user)
    RETURNING id INTO v_supplier;
  INSERT INTO public.market_suppliers (tenant_id, supplier_id, created_by) VALUES (v_tenant, v_supplier, v_user);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'supplier.create', 'supplier', v_supplier, jsonb_build_object('name', v_name, 'marketSeller', true));
  RETURN v_supplier;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.market_supplier() FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.market_supplier() TO app_runtime;
--> statement-breakpoint

-- ── hand-written: a quick market purchase is written once ───────────────────────────────────────
-- Made with a draft order; then its goods received note (a draft against that order), its bill
-- (a draft from the order's supplier) and its payment (a draft to that supplier) are named, in
-- that order, once each. Nothing else about it ever changes, and it is never removed.
CREATE FUNCTION app.check_market_purchase() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_market uuid;
  v_order public.purchase_orders%ROWTYPE;
  v_receipt public.goods_receipts%ROWTYPE;
  v_bill public.supplier_bills%ROWTYPE;
  v_payment public.supplier_payments%ROWTYPE;
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'a quick market purchase is never removed' USING ERRCODE = 'SE268';
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT m.supplier_id INTO v_market FROM public.market_suppliers m WHERE m.tenant_id = NEW.tenant_id;
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := app.current_user_id();
    NEW.created_at := now();
    IF NEW.receipt_id IS NOT NULL OR NEW.bill_id IS NOT NULL OR NEW.payment_id IS NOT NULL THEN
      RAISE EXCEPTION 'a quick market purchase starts with its order alone' USING ERRCODE = 'SE268';
    END IF;
    -- The order is held until the transaction ends, so it is not changed, or removed and put back
    -- under its id, meanwhile. One that is not there refuses the purchase here.
    SELECT o.* INTO v_order FROM public.purchase_orders o WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.order_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'no such order' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_order.status <> 'draft' THEN
      RAISE EXCEPTION 'a quick market purchase is made with a draft order' USING ERRCODE = 'SE268';
    END IF;
    -- The seller is named here when, and only when, the order is to the market supplier.
    IF (v_order.supplier_id IS NOT DISTINCT FROM v_market) <> (NEW.seller_name IS NOT NULL) THEN
      RAISE EXCEPTION 'a seller who is not on the list is named on the purchase; a supplier on the list is not named again' USING ERRCODE = 'SE268';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.order_id <> OLD.order_id OR NEW.client_key <> OLD.client_key
     OR NEW.seller_name IS DISTINCT FROM OLD.seller_name OR NEW.seller_phone IS DISTINCT FROM OLD.seller_phone OR NEW.memo_no IS DISTINCT FROM OLD.memo_no
     OR NEW.created_at <> OLD.created_at OR NEW.created_by <> OLD.created_by
     OR (OLD.receipt_id IS NOT NULL AND NEW.receipt_id IS DISTINCT FROM OLD.receipt_id)
     OR (OLD.bill_id IS NOT NULL AND NEW.bill_id IS DISTINCT FROM OLD.bill_id)
     OR (OLD.payment_id IS NOT NULL AND NEW.payment_id IS DISTINCT FROM OLD.payment_id)
     OR (NEW.bill_id IS NOT NULL AND NEW.receipt_id IS NULL)
     OR (NEW.payment_id IS NOT NULL AND NEW.bill_id IS NULL) THEN
    RAISE EXCEPTION 'a quick market purchase names its goods received note, its bill and its payment once, in that order, and nothing else about it changes' USING ERRCODE = 'SE268';
  END IF;
  SELECT o.* INTO v_order FROM public.purchase_orders o WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.order_id FOR SHARE;
  -- Each document it names is held the same way, and refused when not there.
  IF OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL THEN
    SELECT r.* INTO v_receipt FROM public.goods_receipts r WHERE r.tenant_id = NEW.tenant_id AND r.id = NEW.receipt_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'no such goods received note' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_receipt.status <> 'draft' OR v_receipt.order_id IS DISTINCT FROM NEW.order_id THEN
      RAISE EXCEPTION 'a quick market purchase''s goods received note is a draft against its order' USING ERRCODE = 'SE268';
    END IF;
  END IF;
  IF OLD.bill_id IS NULL AND NEW.bill_id IS NOT NULL THEN
    SELECT b.* INTO v_bill FROM public.supplier_bills b WHERE b.tenant_id = NEW.tenant_id AND b.id = NEW.bill_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'no such bill' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_bill.status <> 'draft' OR v_bill.supplier_id IS DISTINCT FROM v_order.supplier_id THEN
      RAISE EXCEPTION 'a quick market purchase''s bill is a draft from its order''s supplier' USING ERRCODE = 'SE268';
    END IF;
  END IF;
  IF OLD.payment_id IS NULL AND NEW.payment_id IS NOT NULL THEN
    SELECT p.* INTO v_payment FROM public.supplier_payments p WHERE p.tenant_id = NEW.tenant_id AND p.id = NEW.payment_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'no such payment' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_payment.status <> 'draft' OR v_payment.supplier_id IS DISTINCT FROM v_order.supplier_id THEN
      RAISE EXCEPTION 'a quick market purchase''s payment is a draft to its order''s supplier' USING ERRCODE = 'SE268';
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_market_purchase() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER market_purchases_check
