-- Asked when the transaction ends: a quick market purchase is never left with goods not yet in,
-- a bill for something else, or a bill unpaid or paid in part.
CREATE FUNCTION app.check_market_purchase_whole() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_purchase public.market_purchases%ROWTYPE;
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NULL;
  END IF;
  SELECT m.* INTO v_purchase FROM public.market_purchases m WHERE m.tenant_id = NEW.tenant_id AND m.id = NEW.id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF v_purchase.receipt_id IS NULL OR v_purchase.bill_id IS NULL OR v_purchase.payment_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.purchase_orders o
    JOIN public.goods_receipts r ON r.tenant_id = o.tenant_id AND r.id = v_purchase.receipt_id
    JOIN public.supplier_bills b ON b.tenant_id = o.tenant_id AND b.id = v_purchase.bill_id
    JOIN public.supplier_payments p ON p.tenant_id = o.tenant_id AND p.id = v_purchase.payment_id
    WHERE o.tenant_id = v_purchase.tenant_id AND o.id = v_purchase.order_id AND o.status = 'submitted'
      -- the goods: one posted note against the order, for all of every line
      AND r.status = 'posted' AND r.order_id = o.id
      AND NOT EXISTS (
        SELECT 1 FROM public.purchase_order_lines l
        WHERE l.tenant_id = o.tenant_id AND l.order_id = o.id
          AND l.quantity IS DISTINCT FROM (SELECT sum(g.quantity) FROM public.goods_receipt_lines g
                                            WHERE g.tenant_id = l.tenant_id AND g.receipt_id = r.id AND g.order_line_id = l.id))
      -- the bill: posted, from the same supplier, for those goods and nothing else, at the
      -- order's total, with no tax on it and nothing withheld
      AND b.status = 'posted' AND b.supplier_id = o.supplier_id AND b.total = o.total AND b.amount = o.total
      AND b.sales_tax = 0 AND b.provincial_tax = 0 AND b.withheld = 0 AND b.payable = b.total
      AND NOT EXISTS (
        SELECT 1 FROM public.supplier_bill_lines bl
        WHERE bl.tenant_id = b.tenant_id AND bl.bill_id = b.id
          AND (bl.kind <> 'goods' OR NOT EXISTS (SELECT 1 FROM public.goods_receipt_lines g
                                                 WHERE g.tenant_id = bl.tenant_id AND g.id = bl.receipt_line_id AND g.receipt_id = r.id)))
      -- the money: one posted payment to the same supplier, all of it against this bill
      AND p.status = 'posted' AND p.supplier_id = o.supplier_id AND p.amount = b.total
      AND (SELECT count(*) FROM public.supplier_payment_allocations a WHERE a.tenant_id = p.tenant_id AND a.payment_id = p.id) = 1
      AND EXISTS (SELECT 1 FROM public.supplier_payment_allocations a
                  WHERE a.tenant_id = p.tenant_id AND a.payment_id = p.id AND a.bill_id = b.id AND a.amount = b.total)
  ) THEN
    RAISE EXCEPTION 'a quick market purchase is made whole at once: its order, the goods received for all of it, the bill for those goods, and the payment that settles the bill in full' USING ERRCODE = 'SE268';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_market_purchase_whole() FROM PUBLIC;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER market_purchases_whole
  AFTER INSERT OR UPDATE ON public.market_purchases
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.check_market_purchase_whole();
--> statement-breakpoint
ALTER TABLE public.market_purchases ENABLE ALWAYS TRIGGER market_purchases_whole;
