-- ── hand-written: the market seller is bought from only this way ────────────────────────────────
-- An order to the market supplier is submitted only as a quick market purchase's own. Runs after
-- purchase_orders_check (triggers of the same kind fire in the order of their names).
CREATE FUNCTION app.check_market_order() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF NEW.status = 'submitted' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'submitted')
     AND EXISTS (SELECT 1 FROM public.market_suppliers m WHERE m.tenant_id = NEW.tenant_id AND m.supplier_id = NEW.supplier_id)
     AND NOT EXISTS (SELECT 1 FROM public.market_purchases p WHERE p.tenant_id = NEW.tenant_id AND p.order_id = NEW.id) THEN
    RAISE EXCEPTION 'the market seller is bought from only through a quick market purchase, and is paid at once' USING ERRCODE = 'SE267';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_market_order() FROM PUBLIC;
--> statement-breakpoint
