     AND EXISTS (SELECT 1 FROM public.market_suppliers m WHERE m.tenant_id = NEW.tenant_id AND m.supplier_id = NEW.supplier_id)
     AND NOT EXISTS (SELECT 1 FROM public.market_purchases p WHERE p.tenant_id = NEW.tenant_id AND p.bill_id = NEW.id) THEN
    RAISE EXCEPTION 'the market seller is bought from only through a quick market purchase, and is paid at once' USING ERRCODE = 'SE267';
  END IF;
  RETURN NEW;
END $$;
