-- ── hand-written: the market supplier stays what it is ──────────────────────────────────────────
-- Renamed or given a code: yes. Archived, registered for tax, or given an NTN, STRN or CNIC: no.
-- Every purchase from a seller who is not on the list needs it, and its tax identity would be
-- no seller's.
CREATE FUNCTION app.check_market_supplier() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.market_suppliers m WHERE m.tenant_id = NEW.tenant_id AND m.supplier_id = NEW.id)
     AND (NEW.archived_at IS NOT NULL OR NEW.registration_type <> 'unregistered' OR NEW.ntn IS NOT NULL OR NEW.strn IS NOT NULL OR NEW.cnic IS NOT NULL
          OR NEW.atl_status <> 'unknown') THEN
    RAISE EXCEPTION 'the market seller is not archived, registered for tax, or given a tax identity' USING ERRCODE = 'SE269';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_market_supplier() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER suppliers_market
  BEFORE UPDATE ON public.suppliers
